import { Mesh, PlaneGeometry, Group } from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, step, length, max, min, mix, smoothstep, uniform, time } from 'three/tsl';
import { gsap } from 'gsap';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group: ThreeGroup, Mesh: ThreeMesh, PlaneGeometry: ThreePlaneGeometry } = THREE;

  // Root group for the card
  const root = new ThreeGroup();

  // Card dimensions
  const CARD_W = 2.4;
  const CARD_H = 3.2;
  const CORNER = 0.06;
  const BORDER = 0.006;
  const BORDER_COLOR = '#2a2a33';
  const ALBEDO = '#16161d';
  const BACKGROUND = '#0b0b10';

  // Plane geometry
  const geometry = new ThreePlaneGeometry(CARD_W, CARD_H);
  geometry.rotateX(-Math.PI / 2); // face forward

  // Node material with rounded rect + border
  const uvNode = uv();
  const pos = uvNode.mul(vec2(CARD_W, CARD_H));
  const half = vec2(CARD_W, CARD_H).mul(0.5);
  const dist = max(abs(pos.sub(half)).sub(vec2(CORNER, CORNER)), 0.0);
  const borderMask = step(dist.length(), BORDER);
  const baseColor = vec3(...ALBEDO.match(/\w\w/g).map(c => parseInt(c, 16) / 255));
  const borderCol = vec3(...BORDER_COLOR.match(/\w\w/g).map(c => parseInt(c, 16) / 255));
  const color = mix(baseColor, borderCol, borderMask);
  const material = new MeshStandardNodeMaterial({
    color,
    roughness: 0.5,
    metalness: 0.0,
  });

  const cardMesh = new ThreeMesh(geometry, material);
  root.add(cardMesh);

  // Header strip (machined)
  const headerH = 0.08;
  const headerGeom = new ThreePlaneGeometry(CARD_W, headerH);
  headerGeom.translate(0, 0, (CARD_H / 2) - (headerH / 2));
  const headerMat = new MeshStandardNodeMaterial({
    color: 0x16161d,
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
    anisotropy: 0.6,
  });
  const headerMesh = new ThreeMesh(headerGeom, headerMat);
  root.add(headerMesh);

  // Text layout helpers
  const padding = 0.5; // 2 * base unit (0.25)
  const innerWidth = CARD_W - 2 * padding;
  const startY = CARD_H / 2 - padding - headerH; // top of interior area
  const lineHeight = {
0.25; // base unit

  // Helper to create and position text
  function addText(content, opts, yOffset) {
    const txt = ctx.fontAtlas.createText(content, {
      fontSize: opts.fontSize,
      color: opts.color || '#e8ecf2',
      align: 'center',
      maxWidthPx: innerWidth * 100, // rough conversion
      letterSpacingPx: (opts.letterSpacing || 0) * 100,
    });
    txt.position.set(0, yOffset, 0.01);
    // Ensure material is transparent for fade animation
    txt.traverse((obj) => {
      if (obj.isMesh && obj.material) {
        obj.material.transparent = true;
        obj.material.opacity = 0;
      }
    });
    root.add(txt);
    return txt;
  }

  // Text items from config
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Map role to typography defaults
  const typoMap = {
    'tier-name': { fontSize: 20, letterSpacing: 0.08 },
    price: { fontSize: 62, letterSpacing: -0.01 },
    caption: { fontSize: 9, letterSpacing: 0 },
    feature: { fontSize: 13, letterSpacing: 0 },
    'cta-label': { fontSize: 13, letterSpacing: 0.08 },
  };

  const texts = [];

  // Tier name
  const tierItem = items.find(i => i.role === 'tier-name') || { text: 'ATELIER RESERVE' };
  const tierTypo = typoMap['tier-name'];
  const tierTxt = addText(tierItem.text, tierTypo, startY - lineHeight);
  texts.push(tierTxt);

  // Price
  const priceItem = items.find(i => i.role === 'price') || { text: '$480' };
  const priceTypo = typoMap.price;
  const priceTxt = addText(priceItem.text, priceTypo, startY - 2 * lineHeight);
  texts.push(priceTxt);

  // Caption
  const captionItem = items.find(i => i.role === 'caption') || { text: 'PER MONTH, BILLED ANNUALLY' };
  const captionTypo = typoMap.caption;
  const captionTxt = addText(captionItem.text, captionTypo, startY - 3 * lineHeight);
  texts.push(captionTxt);

  // Feature rows
  const featureItems = items.filter(i => i.role === 'feature');
  const featureTypo = typoMap.feature;
  const featureStartY = startY - 4 * lineHeight - 0.5; // gap after caption
  featureItems.forEach((feat, idx) => {
    const y = featureStartY - idx * (0.375 + 0.006);
    const txt = addText(feat.text, featureTypo, y);
    texts.push(txt);
  });

  // CTA row
  const ctaItem = items.find(i => i.role === 'cta-label') || { text: 'JOIN THE RESERVE' };
  const ctaTypo = typoMap['cta-label'];
  const ctaY = -CARD_H / 2 + padding + 0.36 / 2;
  const ctaTxt = addText(ctaItem.text, ctaTypo, ctaY);
  texts.push(ctaTxt);

  // Animations
  const tl = gsap.timeline({ defaults: { ease: 'power4.out' } });
  tl.from(root.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.9 });
  const featureTl = gsap.timeline({ delay: 0.3 });
  featureItems.forEach((_, i) => {
    const txt = texts[4 + i]; // after tier, price, caption
    featureTl.fromTo(
      txt,
      { y: txt.position.y + 0.2, opacity: 0 },
      { y: txt.position.y, opacity: 1, duration: 0.5, ease: 'power2.out' },
      i * 0.08
    );
  });

  // Cleanup
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    tl.kill();
    featureTl.kill();
    material.dispose();
    headerMat.dispose();
    geometry.dispose();
    headerGeom.dispose();
    // Dispose any textures used by text materials
    texts.forEach(txt => {
      txt.traverse(obj => {
        if (obj.isMesh && obj.material && obj.material.map) {
          obj.material.map.dispose();
        }
        if (obj.isMesh && obj.material) {
          obj.material.dispose();
        }
      });
    });
  };

  return root;
}
